function technologyLogo(name){const map={'Microsoft Graph':['microsoft'],'Azure AI Search':['azure'],'Microsoft Entra ID':['microsoft'],'Postgres + pgvector':['postgres'],'Gemini API':['gemini'],'LangGraph':['langgraph'],'Langfuse':['langfuse'],'TypeScript':['typescript'],'React':['react'],'Python':['python'],'Claude Code':['claude'],'Codex':['openai'],'Claude API':['claude'],'OpenAI API':['openai'],'Microsoft Teams':['teams'],'SharePoint':['sharepoint'],'Azure':['azure'],'Supabase':['supabase'],'Vercel':['vercel'],'Claude Code & Codex':['claude','openai'],'TypeScript, React & Python':['react','python']};return (map[name]||[]).map(id=>`<img class="technology-logo technology-logo-${id}" src="logos/${id}.svg" alt="" width="24" height="24">`).join('')}
function technologyBrand(name){return `<span class="technology-brand">${technologyLogo(name)}<span>${esc(name)}</span></span>`}
let studioView='All';
const studioGroups={Growth:[0,1,2,12],Delivery:[6,7,11],Planning:[3,4,5,8,9,10]};
function studioPreview(i){const lines=showcaseMeta[i].slice(2,5);if(i===0)return `<div class="demo-document"><div class="demo-doc-label">NORTHSTAR / PROPOSAL</div><h4>Operations intelligence pilot</h4><div class="demo-doc-line"></div><div class="demo-doc-line short"></div><div class="demo-doc-section">01 &nbsp; Executive summary <span>Drafted</span></div><div class="demo-doc-section">02 &nbsp; Approach & deliverables <span>Review</span></div></div>`;if(i===12)return `<div class="demo-prospect"><div><span class="mini-initial">N</span><div><b>Northstar Manufacturing</b><small>Operations · Process improvement</small></div><em>94 fit</em></div><div class="demo-message"><span>EMAIL · VERSION 01</span><p>A workflow idea for your operations team</p><div class="demo-doc-line"></div></div></div>`;if(i===5||i===9||i===8)return `<div class="demo-analytics"><div><span>${i===9?'Revenue scenario':'Revenue performance'}</span><b>$3.84M <small>+12.3%</small></b></div><svg viewBox="0 0 280 70" aria-hidden="true"><path d="M0 65L0 58L26 49L52 52L78 35L104 40L130 27L156 31L182 18L208 23L234 10L260 14L280 4L280 65Z" fill="#eee3d8"/><path d="M0 58L26 49L52 52L78 35L104 40L130 27L156 31L182 18L208 23L234 10L260 14L280 4" fill="none" stroke="#a38366" stroke-width="2.5"/></svg></div>`;if(i===6)return `<div class="demo-capacity">${[['Alex Morgan',65],['Taylor Kim',92],['Jordan Ellis',48]].map(([n,v])=>`<div><b>${n}</b><span><i style="width:${v}%"></i></span><small>${v}%</small></div>`).join('')}<p>Weekly capacity · open to adjust assignments</p></div>`;if(i===7||i===11)return `<div class="demo-kanban">${['To do','In progress','Complete'].map((x,n)=>`<div><small>${x}</small><section><span></span><b>${['Confirm scope','Build workspace','Discovery'][n]}</b><em>${['AM','TK','JE'][n]}</em></section></div>`).join('')}</div>`;if(i===1)return `<div class="demo-sequence">${['First email','Follow-up 1','Follow-up 2','Follow-up 3'].map((x,n)=>`<div><i>${n+1}</i><b>${x}</b><small>Day ${[0,3,7,14][n]}</small></div>`).join('')}</div>`;return `<div class="demo-checklist">${lines.map((s,n)=>`<div><span>0${n+1}</span><b>${esc(s)}</b>${icon('check')}</div>`).join('')}</div>`}
function studioCard(i,featured=false){return `<button class="studio-app ${featured?'featured':''}" onclick="nav(${i})"><div class="studio-app-top"><span class="studio-app-icon">${icon(productIcons[i])}</span><div><h3>${esc(toolsList[i][0])}</h3><small>${esc(productStories[i].audience)}</small></div><span class="studio-app-arrow">↗</span></div>${featured?studioPreview(i):`<p>${esc(productStories[i].title)}</p>`}<div class="studio-app-bottom"><span>${esc(showcaseMeta[i][0])}</span>${icon('arrow')}</div></button>`}
function studioHome(){const ids=studioView==='All'?toolsList.map((_,i)=>i):studioGroups[studioView];return `<div class="studio-dashboard"><div class="collection-heading"><div><div class="studio-crumb">NINE-67 / PRODUCT COLLECTION</div><h1>Real workflows.<br>Purpose-built intelligence.</h1><p>Fourteen applications that turn everyday business work into a better way to operate. Choose a product and explore the working experience.</p></div><div class="collection-note"><span class="collection-number">14<span>APPLICATIONS</span></span><p>Designed & built by Nine-67</p><div>Growth <span> / </span> Delivery <span> / </span> Planning</div></div></div><div class="collection-toolbar"><div class="studio-filter">${['All','Growth','Delivery','Planning'].map(c=>`<button class="${studioView===c?'active':''}" onclick="studioView='${c}';render()">${c==='All'?'All applications':c}<span>${c==='All'?toolsList.length:studioGroups[c].length}</span></button>`).join('')}</div><span>Interactive workspaces · Sample data</span></div><section id="studioLibrary" class="collection-grid">${ids.map(i=>`<button class="collection-product" onclick="nav(${i})"><div class="collection-product-top"><span class="studio-app-icon">${icon(productIcons[i])}</span><span>${esc(productStories[i].audience)}</span><span class="collection-index">${String(i+1).padStart(2,'0')}</span></div><h2>${esc(toolsList[i][0])}</h2><p>${esc(studioProductDetails[i][0])}</p><div class="collection-preview">${studioPreview(i)}</div><div class="collection-product-bottom"><span>${esc(showcaseMeta[i][0])}</span><span>Open workspace ${icon('arrow')}</span></div></button>`).join('')}</section><div class="collection-stack"><div><h2>Your workflow. Your environment.</h2><p>We tailor the application and integrations to the way your team works.</p></div><div><span>Claude API</span><span>OpenAI API</span><span>Microsoft Teams</span><span>SharePoint</span><span>Azure</span><span>Supabase</span><span>Vercel</span></div></div><p class="studio-disclosure">Interactive showcase · Sample data · Simulated AI · No live messages sent</p></div>`}
const studioProductDetails=[["Turn requirements into a persuasive, reviewable proposal.", "Start a conversation, upload the RFP, and shape the response with an AI partner that keeps requirements and your approach in view.", [["Understand the brief", "Extract deliverables, deadlines, evaluation criteria, and unanswered questions from the RFP."], ["Build the response", "Develop the narrative, scope, delivery plan, and assumptions through a guided conversation."], ["Prepare for approval", "Review requirement coverage, refine sections, and hand an editable draft to your team."]], ["Ground proposal drafts in the RFP and approved reference material.", "Bring SharePoint case studies into the brief and route review discussions through Microsoft Teams.", "Keep proposal versions and requirements in Supabase; deliver the workspace through Vercel with Azure services selected for the client."]], ["Make every webinar the start of a relevant conversation.", "Give marketing a workspace to turn the recording, transcript, and attendee context into outreach that sounds informed, personal, and ready to review.", [["Capture the substance", "Identify the webinar’s key ideas, audience questions, and useful follow-up resources."], ["Write by audience", "Tailor the opening email to attendee interests, engagement, and your preferred tone."], ["Build the cadence", "Prepare three follow-ups with distinct value, timing, and calls to action."]], ["Summarize the transcript and draft audience-specific emails plus three follow-ups.", "Use SharePoint for recordings and approved content; coordinate campaign review in Microsoft Teams.", "Store audience segments and draft cadences in Supabase, present the editor on Vercel, and use Azure for client-specific processing."]], ["Give sales a reasoned next-best lead list.", "Connect scattered lead signals to account context so sellers can understand who to prioritize, why they matter, and what to do next.", [["Connect the signals", "Bring lead records, engagement, and account information into one working view."], ["Explain the priority", "Compare fit and intent, flag missing evidence, and surface the reasons behind a recommendation."], ["Assign the next step", "Review the recommendation, select an owner, and prepare a focused follow-up."]], ["Correlate lead signals, explain priority, and suggest an appropriate next action.", "Reference qualification guidance from SharePoint and coordinate lead handoffs in Microsoft Teams.", "Model leads, ownership, and scoring history in Supabase with a Vercel interface and Azure integration services as required."]], ["Pressure-test an idea before taking it to market.", "Explore how different simulated personas might respond to a message, proposition, or concept—and use the differences to improve your next version.", [["Frame the experiment", "Choose the message, audience personas, and questions you want to investigate."], ["Compare reactions", "Inspect simulated objections, points of confusion, and language that resonates."], ["Refine the concept", "Compare responses across personas and develop a clearer message to validate with real people."]], ["Generate simulated persona responses and synthesize themes; this is exploratory feedback, not human research.", "Organize source briefs in SharePoint and discuss findings with stakeholders in Microsoft Teams.", "Retain persona definitions and experiment versions in Supabase, serve the lab on Vercel, and configure Azure services to fit data needs."]], ["Build a budget your departments can explain.", "Give department leaders a conversational planning workspace that connects goals, spending assumptions, and line items to a coherent company plan.", [["Start with the plan", "Set department goals and bring in prior spending, headcount, and known commitments."], ["Shape the numbers", "Ask AI to structure line items, examine assumptions, and identify gaps in the plan."], ["Reconcile the request", "Compare departments, inspect changes, and prepare a budget for leadership review."]], ["Translate planning conversations into budget structures and explain changes against the baseline.", "Use SharePoint for supporting schedules and Microsoft Teams for department review discussions.", "Store budget lines and scenarios in Supabase, deliver the planning interface on Vercel, and use Azure for enterprise data connections."]], ["See what is driving revenue—and what needs attention.", "Bring historical performance, current pipeline, and the forward outlook into one leadership workspace with a clear path from the headline to the underlying detail.", [["Read performance", "Compare revenue, attainment, and sales trends against the selected period."], ["Inspect the pipeline", "Explore opportunity mix, stage movement, and exposure across teams or accounts."], ["Discuss the outlook", "Surface changes, ask questions about the numbers, and identify decisions for the next review."]], ["Explain movements in sales metrics and summarize the evidence behind the current outlook.", "Reference sales review packs in SharePoint and bring leadership discussion into Microsoft Teams.", "Organize sales snapshots in Supabase, display interactive analysis through Vercel, and connect source systems through Azure where needed."]], ["Match the work ahead to the capacity you actually have.", "Help delivery leaders balance projects, people, and availability in one planning workspace, with AI support for identifying pressure before it affects delivery.", [["Map the demand", "Review upcoming tasks, project needs, owners, and delivery dates."], ["Balance capacity", "Compare workloads and availability to spot overload, gaps, and competing commitments."], ["Adjust the plan", "Explore reassignment options and review the effect on the team before committing changes."]], ["Identify capacity conflicts and suggest assignment options with reasons for review.", "Connect resource planning with Microsoft Teams discussions and SharePoint project documentation.", "Track people, tasks, and allocations in Supabase; deliver scheduling on Vercel and use Azure for organizational integrations."]], ["Give everyone a shared place to move the project forward.", "Bring internal teams, clients, and contractors around the same project context, with role-specific views for the people doing the work and those approving it.", [["Establish the workspace", "Organize the project plan, participants, milestones, and important decisions."], ["Keep context together", "Connect files, conversations, tasks, and updates to the work they support."], ["Coordinate across roles", "Preview client, contractor, and internal perspectives with the right information for each."]], ["Summarize project context, surface unresolved questions, and help participants find relevant information.", "Microsoft Teams supports project conversation; SharePoint provides the connected document workspace.", "Use Supabase for project and role data, Vercel for the shared portal, and Azure for identity and enterprise integration options."]], ["Turn a library of reports into a usable picture of the business.", "Give decision-makers a single visual workspace to explore reports, compare findings, and ask questions while keeping the original source in reach.", [["Bring reports together", "Organize reporting by business area, period, and the questions it can answer."], ["Explore the evidence", "Move between visual summaries, detailed views, and the source context behind a finding."], ["Find the implication", "Ask AI to connect themes, explain changes, and prepare a focused executive summary."]], ["Synthesize report content and explain cross-report themes with supporting source context.", "Connect SharePoint report libraries and share review discussions through Microsoft Teams.", "Use Supabase for report metadata and saved views, Vercel for the visual studio, and Azure for document-processing integrations."]], ["Make the assumptions behind the forecast visible.", "Give executives a scenario workspace to connect historical results, business drivers, and future expectations—and see how changing an assumption changes the outlook.", [["Establish a baseline", "Review historical performance and set the starting point for the planning period."], ["Change the drivers", "Adjust growth and operating assumptions and inspect the resulting projection."], ["Compare the scenarios", "Evaluate alternatives side by side and explain the choices behind the preferred plan."]], ["Help articulate assumptions, explain scenario differences, and draft an executive outlook.", "Use SharePoint for planning inputs and Microsoft Teams for forecast review and discussion.", "Keep scenario inputs and versions in Supabase, run the interface on Vercel, and use Azure to connect enterprise data sources."]], ["Know what the investment needs to deliver before you build.", "Evaluate a project’s expected benefit against its full cost, then test whether the business case holds up when the assumptions change.", [["Model the investment", "Account for build costs, recurring costs, adoption, and the time needed to realize value."], ["Quantify the benefit", "Translate time savings, cost reduction, or revenue contribution into explicit assumptions."], ["Test the case", "Compare ROI and payback, change sensitive inputs, and prepare a reasoned investment discussion."]], ["Help structure the business case and challenge benefit assumptions; financial results follow the entered calculation inputs.", "Keep supporting estimates in SharePoint and coordinate investment review through Microsoft Teams.", "Store cost models and scenario versions in Supabase, deliver the calculator on Vercel, and use Azure for client-specific data connections."]], ["Give clients a clear view of what is being built for them.", "Bring active projects, milestones, decisions, and delivery risks into one portfolio workspace so clients and the delivery team can stay aligned.", [["See the portfolio", "Review project health, owners, progress, and the next important milestone."], ["Open the detail", "Inspect the delivery plan, outstanding decisions, and blockers for an individual initiative."], ["Keep progress clear", "Use AI to summarize updates and prepare the questions that need attention."]], ["Turn project updates into concise status summaries and surface unresolved risks and decisions.", "Link SharePoint deliverables and connect client and delivery discussions through Microsoft Teams.", "Track initiatives, milestones, and decisions in Supabase with a Vercel portal and Azure integration options."]], ["Wake up to a researched prospecting queue.", "Create a nightly research brief, review promising accounts, and turn the findings into three distinct email and LinkedIn content directions before anything is sent.", [["Define the search", "Set the ideal customer profile, target signals, and the focus of the nightly research brief."], ["Review the accounts", "Inspect company context, fit reasoning, and the research behind each recommendation."], ["Choose the angle", "Compare three versions of email and LinkedIn content, refine the language, and prepare a human-reviewed draft."]], ["Synthesize account research and draft three differentiated email and LinkedIn content angles.", "Use SharePoint for approved messaging and Microsoft Teams for review of the prospecting queue.", "Keep briefs, accounts, and draft versions in Supabase; deliver the review app on Vercel with Azure orchestration options."]]];
const studioTechnologyHeadings=[["RFP-grounded proposal drafting", "Approved content & proposal reviews", "Requirements, drafts & version history"], ["Transcript-to-email personalization", "Webinar assets & campaign approvals", "Attendee segments & follow-up cadences"], ["Lead matching & priority reasoning", "Qualification context & sales handoffs", "Account signals & routing history"], ["Persona reactions & message refinement", "Research briefs & stakeholder feedback", "Experiment runs & concept comparisons"], ["Conversational budget planning", "Department inputs & budget sign-off", "Budget lines, baselines & scenarios"], ["Revenue drivers & pipeline explanations", "Sales review packs & executive discussion", "Sales snapshots & performance analysis"], ["Capacity conflicts & assignment options", "Staffing discussions & delivery context", "Availability, tasks & allocation records"], ["Project summaries & contextual answers", "Shared files & project conversations", "Project roles, decisions & workspace access"], ["Cross-report synthesis & source context", "Report libraries & insight discussions", "Report indexing & saved analytical views"], ["Driver assumptions & scenario narratives", "Planning inputs & forecast reviews", "Baseline models & scenario versions"], ["Benefit assumptions & business-case review", "Cost evidence & investment decisions", "ROI models & sensitivity calculations"], ["Delivery summaries & emerging risks", "Client updates & milestone deliverables", "Portfolio records & decision tracking"], ["Account research & three outreach angles", "Approved messaging & prospect reviews", "Research queues & outreach draft history"], ["Relationship signals & recovery plans", "Client conversations & account reviews", "Health snapshots, renewals & action history"]];
function studioProductIntro(){const p=productStories[current],d=studioProductDetails[current],value=typeof clientValue!=='undefined'?clientValue[current]:null;const action=current>=18?'agentExplore()':current===13?'healthAccount(0)':current===14?'financeDetail(0)':current===15?'caseRecord(0)':current===16?'tab=1;render()':current===17?'profitDetail(0)':'startWalkthrough()';const stack=[['Claude API','OpenAI API'],['Microsoft Teams','SharePoint'],['Vercel','Supabase','Azure']];return `<section class="project-overview" aria-label="About ${esc(toolsList[current][0])}"><div class="project-overview-meta"><span class="project-overview-audience">${esc(p.audience)}</span><span class="project-overview-credit">Designed & built by <b>Nine-67</b></span></div><div class="project-overview-intro"><div class="project-overview-summary"><h1>${esc(toolsList[current][0])}</h1><h2>${esc(d[0])}</h2><p>${esc(d[1])}</p></div><aside class="project-overview-value"><div><h3>The problem it solves</h3><p>${esc(value?value[1]:p.title)}</p></div><div><h3>What your team gets</h3><p>${esc(value?value[2]:p.output)}</p></div></aside></div><section class="project-overview-workflow" aria-label="How the application works"><div class="project-overview-sectionhead"><h2>How it works</h2><button class="overview-example-link" onclick="applicationSetView('example')">Open example application ${icon('arrow')}</button></div><ol>${d[2].map(([title,body],i)=>`<li><span class="project-overview-step">${String(i+1).padStart(2,'0')}</span><div><h3>${esc(title)}</h3><p>${esc(body)}</p></div></li>`).join('')}</ol></section><section class="project-overview-technology" aria-label="Technology behind this application"><div class="project-overview-sectionhead"><h2>What powers this application</h2><span>Selected to fit the client environment</span></div><div class="project-overview-techlist">${studioTechnologyHeadings[current].map((heading,i)=>`<article><div class="project-overview-capability"><span>${['AI assistance','Connected work','Application & data'][i]}</span><h3>${esc(heading)}</h3></div><div class="project-overview-tools">${stack[i].map(name=>technologyBrand(name)).join('')}</div><p>${esc(d[3][i])}</p></article>`).join('')}</div><p class="project-overview-note">Interactive demo with sample data and simulated AI. Integrations are tailored to each implementation.</p></section><div class="project-overview-bottom"><span>${icon('check')} ${esc(p.output)}</span><button onclick="${action}">Explore the workflow ${icon('arrow')}</button></div></section>`}


render=function(){document.body.dataset.application=String(current);if(current>=13){$('#main').innerHTML=(current>=18?agentExperience():current===13?healthExperience():current===14?financialDashboard():current===15?businessCasesExperience():current===16?impactExperience():profitExperience());document.title=toolsList[current][0]+' · Nine-67';}else renderBeforeIntroductions();showcaseSidebar();document.body.classList.remove('product-focus');$('.headerRight').innerHTML=`<nav class="brand-header-nav" aria-label="Showcase navigation"><button onclick="nav(-1);processJump('ourProcess')">Our process</button><button onclick="nav(-1);processJump('ourTechnology')">Technology</button><button onclick="commandPalette()">Applications ${icon('chevron')}</button><span class="brand-header-divider"></span><span class="brand-header-demo">Interactive showcase</span></nav>`;$('#crumb').innerHTML=`<button class="brand-header-wordmark" onclick="nav(-1)" aria-label="AI Applications by Nine-67 home"><span class="ai-wordmark-symbol">AI</span><span class="ai-wordmark-name">Applications<small>BY NINE-67</small></span></button>${current>=0?'<span class="brand-header-breadcrumb">'+esc(toolsList[current][0])+'</span>':''}`;if(current<0){$('#main').innerHTML=studioHome();document.title='AI Applications | Nine-67';}if(current>=0&&current<21)$('#main').insertAdjacentHTML('afterbegin',studioProductIntro())};render();
